<script>
  function fillCalendar(id, offset, count, selectedDays){
    const el=document.getElementById(id);
    for(let i=0;i<offset;i++){const b=document.createElement('button');b.className='blank';b.textContent='';el.appendChild(b)}
    for(let d=1;d<=count;d++){
      const b=document.createElement('button');
      b.className='btn'+(selectedDays.includes(d)?' selected':'');
      b.textContent=d;
      b.addEventListener('click',()=>{b.classList.toggle('selected')});
      el.appendChild(b);
    }
  }
  // November 2025 starts Saturday in a Monday-first calendar; December starts Monday.
  fillCalendar('novDays',5,30,[21,23]);
  fillCalendar('decDays',0,31,[]);

  const notice=document.getElementById('notice');
  function toast(text){notice.textContent=text;notice.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>notice.style.display='none',2300)}
  document.getElementById('photosBtn').addEventListener('click',()=>document.getElementById('photoModal').style.display='block');
