  document.getElementById('saveBtn').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent.includes('Saved')?'♡  Save':'♥  Saved';toast('Added to your wishlist')});
  document.getElementById('reserveBtn').addEventListener('click',()=>toast('Choose your dates to continue'));
