    const extras=grid.querySelectorAll('.extra-amenity');
    if(extras.length){extras.forEach(x=>x.remove());e.currentTarget.textContent='Show all 31 amenities';return}
    const items=['TV','Kitchen','Washer','Heating','Dedicated workspace','Smoke alarm','First aid kit','Coffee maker','Private entrance','Iron'];
